<p><strong>7. Row-Level Security (RLS)</strong></p>
<p>sql</p>
<p>-- Example: Users only see their organization\'s data
CREATE POLICY org_access_policy ON cases
USING (organization_id = current_setting(\'app.current_org_id\')::INTEGER);
-- Example: Users only see their assigned cases
CREATE POLICY caseworker_access_policy ON cases
USING (assigned_to = current_user_id());</p>
<p><strong>8. Migration from Airtable to PostgreSQL</strong></p>
<table>
<thead>
<tr>
<th>Airtable Concept</th>
<th>PostgreSQL Equivalent</th>
</tr>
</thead>
<tbody>
<tr>
<td>Base → Database</td>
<td>Database</td>
</tr>
<tr>
<td>Table → Table</td>
<td>Table</td>
</tr>
<tr>
<td>Record → Row</td>
<td>Row</td>
</tr>
<tr>
<td>Field → Column</td>
<td>Column</td>
</tr>
<tr>
<td>View → Materialized View</td>
<td>Materialized View</td>
</tr>
<tr>
<td>Linked Record → Foreign Key</td>
<td>Foreign Key</td>
</tr>
<tr>
<td>Formula → Computed Column</td>
<td>Generated Column</td>
</tr>
<tr>
<td>Automation → Trigger/Function</td>
<td>PL/pgSQL Function</td>
</tr>
</tbody>
</table>
<p><strong>9. Query Examples</strong></p>
<p>sql</p>
<p>-- Get active cases with funding status
SELECT <em> FROM case_funding_summary WHERE status NOT IN (\'completed\', \'denied\');
-- Get overdue reimbursement requests
SELECT </em> FROM reimbursement_aging WHERE days_aging &gt; 30;
-- Get duplicate alerts
SELECT <em> FROM duplicate_case_alerts ORDER BY detected_at DESC;
-- Get task metrics for dashboard
SELECT </em> FROM task_metrics;
-- Get all progress for a case
SELECT * FROM progress_ledger WHERE case_id = 123 ORDER BY event_timestamp DESC;</p>
